// Google Calendar API gibt { items: [...] } zurück
const calendarResponse = $input.first().json;
const events = calendarResponse.items || [];

const existingEvents = events.map(event => ({
  start: new Date(event.start.dateTime || event.start.date),
  end: new Date(event.end.dateTime || event.end.date)
}));

// Aktuelle Zeit in Berlin ermitteln
const now = new Date();
const nowBerlin = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));

const slots = [];
const slotDuration = 20; // Minuten
const maxSlots = 6;
const maxWorkingDays = 5;
let workingDaysChecked = 0;

for (let dayOffset = 0; workingDaysChecked < maxWorkingDays && slots.length < maxSlots; dayOffset++) {
  // Datum in Berlin berechnen
  const checkDate = new Date(nowBerlin);
  checkDate.setDate(checkDate.getDate() + dayOffset);

  // Nur Mo-Fr (1-5)
  const weekday = checkDate.getDay();
  if (weekday === 0 || weekday === 6) continue;
  workingDaysChecked++;

  // Slots von 09:00 bis 17:30 (letzter 20-Min-Slot startet 17:10, endet 17:30)
  for (let hour = 9; hour < 18 && slots.length < maxSlots; hour++) {
    for (let minute = 0; minute < 60 && slots.length < maxSlots; minute += slotDuration) {
      // Slot in Berliner Zeit konstruieren
      const slotBerlin = new Date(checkDate);
      slotBerlin.setHours(hour, minute, 0, 0);

      const slotEndBerlin = new Date(slotBerlin);
      slotEndBerlin.setMinutes(slotEndBerlin.getMinutes() + slotDuration);

      // Slot muss vor 17:30 enden
      const endLimit = new Date(checkDate);
      endLimit.setHours(17, 30, 0, 0);
      if (slotEndBerlin > endLimit) continue;

      // Slot muss in der Zukunft liegen (Berliner Zeit)
      if (slotBerlin <= nowBerlin) continue;

      // Berlin-Zeiten in UTC konvertieren für Kalender-Vergleich
      // Berliner Datum-String → UTC Date
      const berlinDateStr = slotBerlin.getFullYear() + '-' +
        String(slotBerlin.getMonth() + 1).padStart(2, '0') + '-' +
        String(slotBerlin.getDate()).padStart(2, '0') + 'T' +
        String(slotBerlin.getHours()).padStart(2, '0') + ':' +
        String(slotBerlin.getMinutes()).padStart(2, '0') + ':00';
      const berlinEndStr = slotEndBerlin.getFullYear() + '-' +
        String(slotEndBerlin.getMonth() + 1).padStart(2, '0') + '-' +
        String(slotEndBerlin.getDate()).padStart(2, '0') + 'T' +
        String(slotEndBerlin.getHours()).padStart(2, '0') + ':' +
        String(slotEndBerlin.getMinutes()).padStart(2, '0') + ':00';

      // Temporäre Dates für Konfliktprüfung (als Europe/Berlin interpretiert)
      const slotStartUTC = new Date(berlinDateStr + '+02:00');
      const slotEndUTC = new Date(berlinEndStr + '+02:00');

      // Prüfen ob Slot mit bestehendem Termin kollidiert
      const hasConflict = existingEvents.some(event =>
        slotStartUTC < event.end && slotEndUTC > event.start
      );

      if (!hasConflict) {
        const dayNames = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
        const dd = String(slotBerlin.getDate()).padStart(2, '0');
        const mm = String(slotBerlin.getMonth() + 1).padStart(2, '0');
        const yyyy = slotBerlin.getFullYear();
        const hh = String(slotBerlin.getHours()).padStart(2, '0');
        const min = String(slotBerlin.getMinutes()).padStart(2, '0');

        slots.push({
          start: slotStartUTC.toISOString(),
          end: slotEndUTC.toISOString(),
          display: `${dayNames[slotBerlin.getDay()]}, ${dd}.${mm}.${yyyy} um ${hh}:${min} Uhr`
        });
      }
    }
  }
}

return [{ json: { available_slots: slots, count: slots.length } }];
